export const getGetGoodwillBatchRowsUrl = (batchId: string,
    params?: GetGoodwillBatchRowsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/goodwill/v2/batches/${batchId}/rows?${stringifiedParams}` : `/api/goodwill/v2/batches/${batchId}/rows`
}

